package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; public final class DataTableSvgRenderer { public String render(DataTableDiagramSpecV1 s){int p=s.viewport().padding(),w=s.viewport().width()-2*p,h=s.viewport().height()-2*p;var b=new StringBuilder("<rect x=\"").append(p).append("\" y=\"").append(p).append("\" width=\"").append(w).append("\" height=\"").append(h).append("\" fill=\"#FFFFFF\" stroke=\"#000000\"/>");int cols=Math.max(1,s.columnHeaderTemplates().size()),rows=Math.max(1,s.rowHeaderTemplates().size()),cw=w/cols,rh=h/rows;for(int i=1;i<cols;i++)b.append("<line x1=\"").append(p+i*cw).append("\" y1=\"").append(p).append("\" x2=\"").append(p+i*cw).append("\" y2=\"").append(p+h).append("\" stroke=\"#000000\"/>");for(int i=1;i<rows;i++)b.append("<line x1=\"").append(p).append("\" y1=\"").append(p+i*rh).append("\" x2=\"").append(p+w).append("\" y2=\"").append(p+i*rh).append("\" stroke=\"#000000\"/>");for(var cell:s.cells())b.append("<text x=\"").append(p+cell.column()*cw+4).append("\" y=\"").append(p+cell.row()*rh+16).append("\">").append(escape(cell.textTemplate())).append("</text>");for(var cell:s.highlightedCells())b.append("<rect x=\"").append(p+cell.column()*cw).append("\" y=\"").append(p+cell.row()*rh).append("\" width=\"").append(cw).append("\" height=\"").append(rh).append("\" fill=\"none\" stroke=\"#FF0000\"/>");return b.toString();} private String escape(String x){return x==null?"":x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");} }
